d `obst`.`Account_ID` = `rate`.`Account_ID` and `t`.`Type_ID` = `rate`.`FromTill` and `obst`.`Type_ID` = `rate`.`ToTill` and `action`.`ActionDate` between `rate`.`BeginDate` and `rate`.`EndDate`),0) AS `Exchanged`,ifnull((select sum(`action`.`Amount`) from (`action` left join `actiontype` on(`action`.`AType_ID` = `actiontype`.`id`)) where `actiontype`.`shortname` in ('E','Ex') and `action`.`Rate_ID` = `rate`.`ID`),0) AS `Expenditures`,ifnull((select sum(case when lcase(`tt`.`Name`) = 'syr' and lcase(`ct`.`Name`) = 'usd' and `at`.`shortname` = 'E' then `a`.`Amount` else 0 end) from ((((`action` `a` join `actiontype` `at` on(`at`.`id` = `a`.`AType_ID`)) join `till` `t` on(`a`.`Till_ID` = `t`.`ID`)) join `tilltypes` `tt` on(`tt`.`ID` = `t`.`Type_ID`)) left join `tilltypes` `ct` on(`ct`.`ID` = `a`.`currency_tilltype_id`)) where `t`.`Account_ID` = `rate`.`Account_ID`),0) AS `Expenditures_USD`,`obsr`.`ID` AS `ObserveRate_ID`,`obsr`.`Name` AS `ObserveRate` from (((((`rate` left join `rate` `obsr` on(`obsr`.`ID` = `rate`.`ObserveRate_ID`)) left join `account` on(`rate`.`Account_ID` = `account`.`ID`)) left join `subproject` on(`subproject`.`ID` = `account`.`SubProject_ID`)) left join `project` on(`project`.`ID` = `subproject`.`Project_ID`)) left join `city` on(`city`.`ID` = `subproject`.`City_ID`))
